-- Spanish for the written library (Story/Library), part 3: dead phones' texts from the closure (July 6-9: the roads
-- sealed, the fence, the curfew). The English line is the key.
return {
    ["31W [blocked at the bridge|fenced at the county line]. [lonnie|trucker] says tanks on the median. kayla can't cross"] = "la 31W [bloqueada en el puente|cercada en la línea del condado]. [lonnie|un camionero] dice q hay tanques en el camellón. kayla no puede cruzar",
    ["Bobby left [with travis|on his board] [tuesday|yesterday] morning. Said checking on kayla. Hasn't texted since."] = "Bobby se fue [con travis|en su patineta] [el martes|ayer] en la mañana. Dijo que iba a ver a kayla. No ha escrito desde entonces.",
    ["[went up on the roof|drove to the water tower] for signal. [one bar|two bars] for a minute. kayla came through: im safe"] = "[me subí al techo|manejé hasta el tanque de agua] por señal. [una rayita|dos rayitas] un minuto. llegó un mensaje de kayla: estoy a salvo",
    ["missy says [motel's full|no more rooms]. [people sleeping|families camped] in the lot. power flickered twice."] = "missy dice [q el motel está lleno|q ya no hay cuartos]. [gente durmiendo|familias acampando] en el estacionamiento. la luz parpadeó dos veces.",
    ["Kayla's [at megan's dorm|stuck in louisville]. [Megan's mom|her ride] can't get through. We'll get her."] = "Kayla está [en el dormitorio de megan|atorada en louisville]. [La mamá de Megan|Quien la iba a traer] no puede pasar. Nosotros vamos por ella.",
    ["[Coach Burris|Dale] rounded up [half the team|six boys] at the school. Checking houses. Bobby wasn't there. Travis either."] = "[El coach Burris|Dale] juntó a [medio equipo|seis muchachos] en la escuela. Están revisando casas. Bobby no estaba. Travis tampoco.",
    ["heard [shots|something] near the lumberyard [last night|around 2]. nobody goes that way now. bobby know those woods."] = "se oyeron [disparos|algo] cerca del aserradero [anoche|como a las 2]. ya nadie va por ahí. bobby conoce ese bosque.",
    ["climbed the water tower for a bar. [wilson's place is dark|the hendersons have a light on]. [meet at the corner|text when u see this]"] = "me subí al tanque de agua por una rayita. [la casa de wilson está a oscuras|los henderson tienen una luz prendida]. [nos vemos en la esquina|escribe cuando veas esto]",
    ["genny's making that noise again. [need oil|spark plug's fouled]. [got any 10w30|borrow from the hendersons]?"] = "el generador hace ese ruido otra vez. [le falta aceite|la bujía está sucia]. [tienes 10w30|le pedimos a los henderson]?",
    ["mrs henderson's grandson showed up. [took her to louisville|loaded her car]. [house is empty now|left the key with me]."] = "llegó el nieto de la sra henderson. [se la llevó a louisville|le cargó el auto]. [la casa ya está vacía|me dejó la llave].",
    ["IGA took [cash only|exact change] today. [Eggs gone|Milk gone] by 8. Your father stood in line two hours"] = "Hoy en el IGA [solo efectivo|solo cambio exacto]. [Ya no había huevos|Ya no había leche] a las 8. Tu papá hizo fila dos horas",
    ["water line at the [school|fire hall] [four blocks|six blocks] long. Bring a wagon. National Guard handing it out"] = "la fila del agua en [la escuela|la estación de bomberos] mide [cuatro cuadras|seis cuadras]. Trae un carrito. La Guardia Nacional la está repartiendo",
    ["[Jims Hardware|The feed store] on [Main|31W] broken into. Pry marks on the back. Deputy Lusk came by noon"] = "Se metieron a [Jims Hardware|la tienda de forraje] de [Main|la 31W]. Marcas de palanca atrás. El alguacil Lusk vino al mediodía",
    ["Curfew is [9 sharp|sundown]. [Deputy|Wade] sat in his cruiser at the corner all day. Said hes tired"] = "El toque de queda es [a las 9 en punto|al ponerse el sol]. [El alguacil|Wade] estuvo en su patrulla en la esquina todo el día. Dijo que está cansado",
    ["gas [five gal|ten gal] max. [pump died|card reader down] at the marathon. Lonnie argued with the kid for ten min"] = "gasolina máximo [cinco galones|diez galones]. [se murió la bomba|no sirve el lector de tarjetas] en la marathon. Lonnie se peleó con el muchacho diez minutos",
    ["Saw [three|four] guys load a [truck|van] at the closed diner on Maple. No plates. Called it in"] = "Vi a [tres|cuatro] tipos cargando [una camioneta|una van] en la cafetería cerrada de Maple. Sin placas. Lo reporté",
    ["Pharmacy [out of|rationing] [insulin|antibiotics|pain meds]. One bottle per person. Mrs Kowalski cried at the counter"] = "La farmacia [se quedó sin|está racionando] [insulina|antibióticos|analgésicos]. Un frasco por persona. La Sra Kowalski lloró en el mostrador",
    ["Register [short|over] forty bucks. [Boss|Owner] said write it off. Back door was jimmied this morning"] = "A la caja le [faltaban|sobraban] cuarenta dólares. [El jefe|El dueño] dijo que lo olvidemos. Esta mañana forzaron la puerta de atrás",
    ["curfew check at [the bridge|the county line]. [Deputy|Wade] made us pop the trunk. Dog in the back didnt help"] = "revisión del toque de queda en [el puente|la línea del condado]. [el alguacil|Wade] nos hizo abrir la cajuela. el perro atrás no ayudó",
    ["[IGA|The Kroger in town] manager [quit|walked out] yesterday. Assistant running it now. Keys on a string"] = "El gerente [del IGA|del Kroger del pueblo] [renunció|se fue] ayer. Ahora lo lleva el asistente. Las llaves en un cordón",
    ["Gas truck came at [4|5] am. [Line formed at midnight|Gone by noon]. Ten gal and cash only"] = "La pipa de gasolina llegó a las [4|5] am. [La fila empezó a medianoche|Para el mediodía ya no había]. Diez galones y solo efectivo",
    ["Water truck [never came|came empty] at the [school|park]. Guard said tomorrow. Fight broke out"] = "La pipa de agua [nunca llegó|llegó vacía] a [la escuela|el parque]. La Guardia dijo que mañana. Se armó una pelea",
    ["someone [kicked in|pried] the [back|side] door at Twiggys. Jimmy slept there. Shotgun by the register"] = "alguien [pateó|forzó] la puerta [de atrás|lateral] de Twiggys. Jimmy durmió ahí. Escopeta junto a la caja",
    ["Deputy [Lusk|Wade] knocked at [8|9]. Asked about the generator. Said hes checking every house"] = "El alguacil [Lusk|Wade] tocó a las [8|9]. Preguntó por el generador. Dijo que está revisando todas las casas",
    ["Landlord [changed the locks|boarded the front] on [Main|Maple]. Note on the door said curfew violation. Marla wont answer"] = "El casero [cambió las cerraduras|tapó el frente] en [Main|Maple]. La nota en la puerta decía violación del toque de queda. Marla no contesta",
    ["saw [a deputy|Wade] [asleep|passed out] in his cruiser at the lot. Engine running. Didnt wake him"] = "vi a [un alguacil|Wade] [dormido|desmayado] en su patrulla en el estacionamiento. Con el motor prendido. No lo desperté",
    ["[IGA|The store] took [IOUs|names] today. List behind the counter. Dad signed for bread and milk"] = "Hoy [en el IGA|en la tienda] [fiaron|anotaron nombres]. Lista detrás del mostrador. Papá firmó por pan y leche",
    ["Curfew [extended to 8|moved to 7]. [Deputy|Wade] said state order. Porch light counts as violation now"] = "El toque de queda [se adelantó a las 8|se movió a las 7]. [El alguacil|Wade] dijo que es orden del estado. La luz del porche ahora cuenta como violación",
    ["Gas station [closed|out] at [2|3]. Sign on the pump said truck hijacked. Lonnie still stuck at the roadblock"] = "La gasolinera [cerró|se quedó sin nada] a las [2|3]. El letrero en la bomba decía que asaltaron la pipa. Lonnie sigue atorado en el retén",
    ["water [truck|tanker] at the [courthouse|fire station] shot at. Guard fired in the air. Line scattered"] = "le dispararon [a la pipa|al tanque] de agua en [el juzgado|la estación de bomberos]. la Guardia disparó al aire. la fila se dispersó",
    ["Pharmacy [boarded up|empty]. [Mrs Kowalski|The pharmacist] left. Note on the door said try Louisville"] = "La farmacia [tapiada|vacía]. [La Sra Kowalski|La farmacéutica] se fue. La nota en la puerta decía intenten en Louisville",
    ["Boss [gave|told] us [the register cash|what was in the safe]. Said go home. Back door was clear"] = "El jefe nos [dio|repartió] [lo de la caja|lo que había en la caja fuerte]. Dijo váyanse a casa. La puerta de atrás estaba libre",
    ["curfew [check|stop] at [every corner|the light]. Deputy alone. Asked where we live"] = "[revisión|parada] del toque de queda en [cada esquina|el semáforo]. El alguacil solo. Preguntó dónde vivimos",
    ["[IGA|The store] [locked the doors|chained the front] at 4. Let us in five at a time. Cash only"] = "[El IGA|La tienda] [cerró las puertas|le puso cadena al frente] a las 4. Nos dejaban entrar de cinco en cinco. Solo efectivo",
    ["Gas [ration cards|coupons] at the [courthouse|town hall]. Two per car. Deputy handing them grim. Line was quiet"] = "[Tarjetas|Cupones] de gasolina en [el juzgado|la alcaldía]. Dos por auto. El alguacil los repartía muy serio. La fila iba callada",
    ["Heard [glass|wood] break at the [vacant|old] house on Elm. Flashlight moving inside. Called 911. Busy"] = "Oí romperse [un vidrio|madera] en la casa [vacía|vieja] de Elm. Una linterna moviéndose adentro. Llamé al 911. Ocupado",
    ["water [ration|limit] now. [Two jugs|One case] per household. Guard checking IDs. Trish got extra"] = "ahora el agua [está racionada|tiene límite]. [Dos garrafones|Una caja] por casa. La Guardia revisa identificaciones. Trish consiguió extra",
    ["Rent dont matter now. [The office is empty|Nobody's collecting]. Keep the cash for [medicine|gas]"] = "La renta ya no importa. [La oficina está vacía|Nadie está cobrando]. Guarda el efectivo para [medicina|gasolina]",
    ["Court date [cancelled|dont matter]. The judge [left town|aint answering]. [Burn the notice|Use it for kindling]"] = "La audiencia [se canceló|ya no importa]. El juez [se fue del pueblo|no contesta]. [Quema el citatorio|Úsalo para prender el fuego]",
    ["ticket [dont matter|threw it out]. Deputy Wade [aint writing tickets|aint at the station]"] = "la multa [ya no importa|la tiré]. el alguacil Wade [ya no pone multas|no está en la estación]",
    ["repo man [aint coming|truck got stuck at the checkpoint]. [Keys in the visor|Let it go]"] = "el de embargos [no va a venir|se quedó atorado en el retén]. [Las llaves en la visera|Olvídalo]",
    ["Bank [locked the doors|phones dead]. Loan [frozen|gone]. [Dont pay|Cant pay anyway]"] = "El banco [cerró las puertas|tiene los teléfonos muertos]. El préstamo [congelado|ya ni existe]. [No pagues|Igual no se puede pagar]",
    ["lottery ticket [in the junk drawer|lost in the car]. [Numbers dont matter|Drawing aint happening]"] = "el billete de lotería [en el cajón de los triques|perdido en el auto]. [los números ya no importan|no va a haber sorteo]",
    ["payday place [boarded up|burned]. [No one to pay|No one to collect]"] = "el de préstamos [tapiado|quemado]. [no hay a quién pagarle|no hay quién cobre]",
    ["Insurance [lapsed|cancelled]. [Nobody's driving|Nobody's billing]. [Save the stamps|Save the envelope]"] = "El seguro [se venció|se canceló]. [Nadie está manejando|Nadie está cobrando]. [Guarda las estampillas|Guarda el sobre]",
    ["landline's dead. [this phone|knox mobile] [is the only|still] works. keep it close"] = "el teléfono fijo murió. [este teléfono|knox mobile] [es lo único q|todavía] funciona. tenlo cerca",
    ["[Your father|Dad] went to the [gun store|hank's] in irvington yesterday. hasn't said what for"] = "[Tu papá|Papá] fue ayer a [la armería|lo de hank] en irvington. no ha dicho para q",
    ["bobby [didn't show|never came] for his shift at the [lumberyard|yard]. tammy says he quit"] = "bobby [no llegó|nunca vino] a su turno en [el aserradero|el patio]. tammy dice q renunció",
    ["[went up|climbed] on the [roof|water tower] for one bar. nothing. where r u"] = "[me subí|trepé] [al techo|al tanque de agua] por una rayita. nada. dnd estás",
    ["[Carl|Trish] called out [sick|again]. Third day. We're short at {jobPlace}"] = "[Carl|Trish] se reportó [enfermo|otra vez]. Tercer día. Nos falta gente en {jobPlace}",
    ["the [truck|car] [won't start|died] at the gas station. walking home. dont wait"] = "[la camioneta|el auto] [no arranca|se murió] en la gasolinera. me voy a pie a casa. no me esperes",
    ["Grandma's [fever|temp] [spiked|went up] last night. dr sato said stay put. we're watching"] = "A la abuela se le [disparó|subió] la [fiebre|temperatura] anoche. dr sato dijo q no nos movamos. la estamos cuidando",
    ["jimmy at twiggys says [back door's|side door's] [locked|open] now. knock three times. he's got the shotgun"] = "jimmy de twiggys dice q la puerta [de atrás|lateral] ahora está [cerrada|abierta]. toquen tres veces. tiene la escopeta",
    ["Deputy lusk [went out|didn't come back] on a [call|domestic] on main hours ago. dispatch quiet"] = "El alguacil lusk [salió|no volvió] de [una llamada|un pleito doméstico] en main hace horas. despacho callado",
    ["[paid|covered] the [visa|mastercard] minimum. 400 left. didnt tell you"] = "[pagué|cubrí] el mínimo de la [visa|mastercard]. quedan 400. no te dije",
    ["army has 31W blocked at [the river|the county line]. lonnie says they turned his rig around"] = "el ejército tiene bloqueada la 31W en [el río|la línea del condado]. lonnie dice q le regresaron el tráiler",
    ["The house phone is dead. [This is the only way now|Only this works now]. Keep it charged"] = "El teléfono de la casa no sirve. [Ahora esta es la única forma|Ahora solo esto funciona]. Mantenlo cargado",
    ["[went upstairs|on the roof] for one bar. [are u ok|where are u]"] = "[subí|en el techo] por una rayita. [estás bien|dónde estás]",
    ["[We're closed|Shop's closed] till further notice. Don't come in. Take care of your family"] = "[Cerramos|El taller está cerrado] hasta nuevo aviso. No vengas. Cuida a tu familia",
    ["31W is fenced at the [bridge|county line]. They said turn around or [else|we will make you]"] = "Pusieron cerca en la 31W en [el puente|la línea del condado]. Dijeron den la vuelta o [ya verán|los obligamos]",
    ["The prison went dark [at 3|before dawn]. Lyle's phone is off. Nobody at the gate"] = "La prisión se quedó a oscuras [a las 3|antes del amanecer]. El teléfono de Lyle está apagado. Nadie en la reja",
    ["Dee's last call on the radio was [4:17|4:22]. Nothing after. I keep listening"] = "La última llamada de Dee por la radio fue a las [4:17|4:22]. Nada después. Sigo escuchando",
    ["Courthouse doors are chained. June stayed with the records. [Don't come in|Stay home]"] = "Las puertas del juzgado tienen cadena. June se quedó con los archivos. [No vengas|Quédate en casa]",
    ["baptist church is full. pastor glen at the door with a list. [we're not on it|he says wait]"] = "la iglesia bautista está llena. el pastor glen en la puerta con una lista. [no estamos|dice q esperemos]",
    ["wade's cruiser is sitting on main st. [door open|keys in it]. no sign of him"] = "la patrulla de wade está en main st. [con la puerta abierta|con las llaves puestas]. ni rastro de él",
    ["Your father walked to the station [hours ago|at dawn]. No word. I'm watching the road"] = "Tu papá se fue caminando a la estación [hace horas|al amanecer]. Nada. Estoy vigilando el camino",
    ["Office closed for good I guess. Keys are [under the mat|at my place]. Don't come in"] = "Supongo que la oficina cerró para siempre. Las llaves están [bajo el tapete|en mi casa]. No vengas",
    ["[wire|a fence] across 31W at the river. some trucker's stuck there with a load of [produce|chickens]"] = "[alambre|una cerca] atravesando la 31W en el río. un camionero está atorado ahí con una carga de [verdura|pollos]",
    ["Line for water at the town hall went around the block. A deputy [turned us away|closed the door] at noon"] = "La fila del agua en la alcaldía le daba la vuelta a la cuadra. Un alguacil [nos regresó|cerró la puerta] al mediodía",
    ["ray's wife texted me. he went to restart KM-12 by the lake [yesterday|this morning]. phone's off since"] = "la esposa de ray me escribió. fue a reiniciar la KM-12 junto al lago [ayer|esta mañana]. tiene el teléfono apagado desde entonces",
    ["Closed till further notice. [Don't come in|Stay home]. The phone guy says the country towers go first"] = "Cerrado hasta nuevo aviso. [No vengas|Quédate en casa]. El de la telefónica dice que las antenas del campo son las primeras en caer",
    ["Gunshots by the river road [last night|around 2]. Your father says it's nothing but he locked the storm door"] = "Disparos por el camino del río [anoche|como a las 2]. Tu papá dice que no es nada pero cerró la contrapuerta con llave",
    ["marla's car is still at the lake office. her purse is on the desk. [cabin 4|the door] wide open"] = "el auto de marla sigue en la oficina del lago. su bolsa está en el escritorio. [la cabaña 4|la puerta] abierta de par en par",
    ["We're staying at the club. There's food and a generator. [There's room|Come if you can]"] = "Nos estamos quedando en el club. Hay comida y un generador. [Hay lugar|Ven si puedes]",
    ["Lights keep flickering. I found the oil lamps. [Your mother's laughing at me|Feels like 1955]"] = "Las luces siguen parpadeando. Encontré las lámparas de aceite. [Tu mamá se está riendo de mí|Parece 1955]",
    ["Your father went to check on Mrs. Clark [an hour ago|before lunch]. He'll be back. He always comes back"] = "Tu papá fue a ver a la Sra. Clark [hace una hora|antes de comer]. Va a volver. Siempre vuelve",
    ["a stranger answered Grandma's phone. said she's [resting|asleep] and hung up. [who was that|im scared]"] = "un desconocido contestó el teléfono de la abuela. dijo q [está descansando|está dormida] y colgó. [quién era|tengo miedo]",
    ["Landline's dead at {jobPlace}. Radio and cell only. Keep the spare battery charged"] = "El teléfono fijo murió en {jobPlace}. Solo radio y celular. Mantengan cargada la batería de repuesto",
    ["trish didnt come home. her sister brought her [go bag|clothes] to the door. nobody would open it"] = "trish no volvió a casa. su hermana le trajo [la maleta de emergencia|ropa] a la puerta. nadie quiso abrir",
    ["Ambulance bay is chained. Walk-ins at the side door only. [Check everyone|Look at their arms]"] = "La entrada de ambulancias tiene cadena. Solo gente a pie por la puerta lateral. [Revisen a todos|Mírenles los brazos]",
    ["supervisor didnt show. were running calls blind. [no radio|half a crew]"] = "el supervisor no vino. estamos atendiendo llamadas a ciegas. [sin radio|con medio equipo]",
    ["Generator diesel gone by [noon|dark]. Emergency circuits only. Ventilators first"] = "El diésel del generador se acaba [al mediodía|al anochecer]. Solo los circuitos de emergencia. Primero los respiradores",
    ["Cordon is up as of 0600. 31W and the interstate both sealed. Report to {jobPlace} in full kit"] = "El cerco está puesto desde las 0600. La 31W y la interestatal selladas. Preséntense en {jobPlace} con equipo completo",
    ["A deputy knocked. Said [stay put|shelter in place] till they sort out the checkpoints. The kids keep asking why"] = "Tocó un alguacil. Dijo [que no nos moviéramos|que nos resguardáramos en casa] hasta que arreglen lo de los retenes. Los niños siguen preguntando por qué",
    ["kayla got turned back at the bridge. shes [sitting in her car|crying] in the kroger lot. [she wont answer|go get her]"] = "a kayla la regresaron en el puente. está [sentada en su auto|llorando] en el estacionamiento del kroger. [no contesta|ve por ella]",
    ["Old Earl on the CB says the wire goes all the way to the river. [Nobody's said how long|We're penned in]"] = "El viejo Earl dice por el CB que el alambre llega hasta el río. [Nadie dice cuánto tiempo|Estamos encerrados]",
    ["went up on the roof for signal. [smoke|an orange glow] toward louisville. [dont go out|stay inside]"] = "me subí al techo por señal. [humo|un brillo naranja] rumbo a louisville. [no salgas|quédate adentro]",
    ["Checkpoint at 31W and 144. Nobody crosses until further notice. That includes family"] = "Retén en la 31W y la 144. Nadie cruza hasta nuevo aviso. Eso incluye a la familia",
    ["Curfew at dark. The deputy said after 9 they [won't ask questions|shoot first]. Pull the shades"] = "Toque de queda al oscurecer. El alguacil dijo que después de las 9 [no van a preguntar|disparan primero]. Baja las persianas",
    ["a soldier at the fence asked to use my phone to text his mom. [he looked 17|he was shaking]"] = "un soldado en la cerca me pidió el teléfono para escribirle a su mamá. [parecía de 17|estaba temblando]",
    ["IGA went cash only. shelves [half empty|bare] by noon. got the last [loaf|gallon of milk]"] = "el IGA ahora es solo efectivo. estantes [medio vacíos|vacíos] al mediodía. agarré [el último pan|el último galón de leche]",
    ["Heard [shots|popping] by the school at 2am. Then a car alarm. Then nothing. [Didn't sleep|Still watching the window]"] = "Se oyeron [disparos|tronidos] por la escuela a las 2am. Luego una alarma de auto. Luego nada. [No dormí|Sigo vigilando la ventana]",
    ["Doug skipped half his route today. Says [four|five] houses on our street don't answer the door"] = "Doug se saltó media ruta hoy. Dice que en [cuatro|cinco] casas de nuestra calle no abren la puerta",
    ["Trish from the hospital says don't come to the ER unless you're [dying|truly desperate]. She's on hour 16"] = "Trish del hospital dice que no vayas a urgencias a menos que [te estés muriendo|sea de vida o muerte]. Lleva 16 horas",
    ["speedway cancelled saturday. first time in 30 years. wendell [cried on the PA|said a prayer instead]"] = "el autódromo canceló lo del sábado. primera vez en 30 años. wendell [lloró por los altavoces|rezó en vez de eso]",
    ["Gus says the cattle bawled all night. Fence held. Something [spooked|was walking around] them"] = "Gus dice que el ganado berreó toda la noche. La cerca aguantó. Algo [lo asustó|andaba dando vueltas alrededor]",
    ["gas line moves one car at a time. cash only. [3 hours|all afternoon] for ten gallons"] = "la fila de la gasolina avanza de auto en auto. solo efectivo. [3 horas|toda la tarde] por diez galones",
    ["dads truck died at the railroad crossing. we [pushed it|coasted] to the shoulder. [bring the jug|come get us]"] = "la camioneta de papá se murió en el cruce del tren. [la empujamos|llegamos en bajada] al acotamiento. [trae el bidón|ven por nosotros]",
    ["Tank's empty at the scales. I'm walking to the truck stop. Don't move the car"] = "Se acabó el tanque en la báscula. Voy caminando a la parada de camiones. No muevas el auto",
    ["Earl says channel 19 has gone quiet. First time in thirty years. [Just static|He sounded scared]"] = "Earl dice que el canal 19 se quedó callado. Primera vez en treinta años. [Pura estática|Se oía asustado]",
    ["girl at the pump crying. [car dead|phone dead]. gave her [my charger|a ride]. she just kept saying her moms name"] = "una muchacha llorando en la bomba. [el auto muerto|el teléfono muerto]. [le di mi cargador|la llevé en el auto]. solo repetía el nombre de su mamá",
    ["Owner says chain the gate and go home. The safe stays. [I'll be back when this blows over|Keys under the mat]"] = "El dueño dice que le pongamos cadena a la reja y nos vayamos. La caja fuerte se queda. [Vuelvo cuando esto pase|Las llaves bajo el tapete]",
    ["trooper told the campers they cant stay on the shoulder. theyre parked in the [church|school] lot now"] = "el patrullero les dijo a los de las casas rodantes q no pueden quedarse en el acotamiento. ahora están en el estacionamiento de [la iglesia|la escuela]",
    ["Gates are chained. Night shift stays inside. [Foreman has the keys|Don't try the fence]"] = "Las rejas tienen cadena. El turno de noche se queda adentro. [El capataz tiene las llaves|No intenten la cerca]",
    ["been inside the plant since [tuesday|3 days]. foreman says wait it out. out of [coffee|cigarettes]"] = "llevo adentro de la planta desde [el martes|hace 3 días]. el capataz dice q aguantemos. ya no hay [café|cigarros]",
    ["Doug came by. He's keeping a list of houses where nobody answers. [Ours isn't on it|Don't be on it]"] = "Vino Doug. Lleva una lista de las casas donde nadie contesta. [La nuestra no está|Que no te anoten]",
    ["climbed the water tower for signal. no smoke from the stacks. [first time ever|plants dark]"] = "me subí al tanque de agua por señal. no sale humo de las chimeneas. [primera vez en la vida|la planta está a oscuras]",
    ["Generator's down. [Rationing flashlights|Rotating watch]. Stay in pairs"] = "Se cayó el generador. [Racionando linternas|Turnos de guardia]. Anden en parejas",
    ["somebody on c shift got sick. they put him in the office. door's locked. nobody goes in"] = "alguien del turno c se enfermó. lo metieron en la oficina. la puerta tiene llave. nadie entra",
    ["Earl hasn't been on the CB since [this morning|yesterday]. Battery maybe. I'll go by"] = "Earl no ha salido en el CB desde [esta mañana|ayer]. Será la batería. Voy a pasar a verlo",
    ["gun store lights are out. nobody at the back. hank's truck is still in the lot"] = "las luces de la armería están apagadas. nadie atrás. la camioneta de hank sigue en el estacionamiento",
    ["Feed store sign says Back Monday. Today's Thursday. [Don't count on it|I wouldn't wait]"] = "El letrero de la tienda de forraje dice Volvemos el lunes. Hoy es jueves. [No cuentes con eso|Yo no esperaría]",
    ["gus didnt show at the Brott place this morning. the cattle bawled all night"] = "gus no llegó al rancho Brott esta mañana. el ganado berreó toda la noche",
    ["No announcements from the speedway in two days. Not even the birds out there"] = "Ni un anuncio del autódromo en dos días. Ni los pájaros se oyen por allá",
    ["The Brott gate is torn open. Cows on the road. Gus's hat [by the gate|in the ditch]"] = "La reja del rancho Brott está arrancada. Vacas en el camino. El sombrero de Gus [junto a la reja|en la zanja]",
    ["becky is sleeping in the stockroom. her moms still in louisville. [bring her stuff|check on her]"] = "becky está durmiendo en la bodega. su mamá sigue en louisville. [llévale sus cosas|ve a verla]",
    ["Mall is chained shut. Nobody in, nobody out. Don't come in"] = "El centro comercial tiene cadena. No entra ni sale nadie. No vengas",
    ["rev lois wont leave the church. somebody has to keep the list she says. [bring her coffee|send food]"] = "la rev lois no quiere salir de la iglesia. alguien tiene q llevar la lista dice. [llévale café|manden comida]",
    ["Mrs. Henderson's door is [open now|still shut]. [Nobody home|There's a note]. I don't want to go in"] = "La puerta de la Sra. Henderson [ahora está abierta|sigue cerrada]. [No hay nadie|Hay una nota]. No quiero entrar",
    ["bunker gate has a new padlock. army lock. [nobody goes up|who has the key]"] = "la reja del búnker tiene un candado nuevo. candado del ejército. [nadie sube|quién tiene la llave]",
    ["Lois read the list at noon. [Eleven|Thirteen] names now. We know most of them"] = "Lois leyó la lista al mediodía. Ya son [once|trece] nombres. Conocemos a casi todos",
    ["Neighbors are doing door checks every morning at 8. Sign the sheet at the church [so they know|or they'll mark you]"] = "Los vecinos pasan casa por casa todas las mañanas a las 8. Firma la hoja en la iglesia [para que sepan|o te van a marcar]",
    ["some names on the church list have a red mark now. lois wont say what it means"] = "algunos nombres de la lista de la iglesia ahora tienen una marca roja. lois no quiere decir q significa",
    ["I took soup to [the Jenkins place|old Mr. Peterson]. Door locked. No answer. I left it on the step"] = "Le llevé sopa [a los Jenkins|al viejo Sr. Peterson]. Puerta con llave. Nadie contestó. La dejé en el escalón",
    ["Two more towers dark. Ray's still not back. Dot's alone on the switchboard"] = "Dos antenas más apagadas. Ray todavía no vuelve. Dot está sola en el conmutador",
    ["The house phone is gone. Dot at Knox Mobile said keep the cell close. She called me hon. [I cried|It helped]"] = "El teléfono de la casa ya no sirve. Dot de Knox Mobile dijo que tenga el celular cerca. Me dijo cariño. [Lloré|Me ayudó]",
    ["Tried calling [three|four] times. All circuits busy. Your mother got my text. Finally"] = "Intenté llamar [tres|cuatro] veces. Todos los circuitos ocupados. A tu mamá le llegó mi mensaje. Por fin",
    ["Went up in the attic for a bar. My message sat in the queue till [2am|4am]. Then it went"] = "Subí al ático por una rayita. Mi mensaje se quedó en cola hasta las [2am|4am]. Luego se fue",
    ["lady at the IGA begging to use somebodys phone. her house phone's dead. i let her use mine"] = "una señora en el IGA rogando q le prestaran un teléfono. el de su casa no sirve. le presté el mío",
    ["back room at twiggys gets two bars. people sleeping by the outlet waiting to charge"] = "en el cuarto de atrás de twiggys hay dos rayitas. gente durmiendo junto al enchufe esperando cargar",
    ["Dot texted me herself. Ray hasn't come back. She's staying at the switchboard alone. Pray for her"] = "Dot me escribió ella misma. Ray no ha vuelto. Se queda sola en el conmutador. Reza por ella",
    ["coach texted everybody. practice cancelled. check on each other he said. [weird|thats not like him]"] = "el coach les escribió a todos. se cancela el entrenamiento. cuídense entre ustedes dijo. [raro|no es normal en él]",
    ["kayla made it to the motel. room 12. phone at 12%. [safe for now|dont tell mom]"] = "kayla llegó al motel. cuarto 12. teléfono al 12%. [a salvo por ahora|no le digas a mamá]",
    ["bobbys board is still by the lumberyard fence. nobody's seen him. or travis"] = "la patineta de bobby sigue junto a la cerca del aserradero. nadie lo ha visto. ni a travis",
    ["heard [screams|shots] by the school at [2|3]am. dad said stay down. quiet now"] = "se oyeron [gritos|disparos] por la escuela a las [2|3]am. papá dijo agáchense. ahora todo callado",
    ["31W is still blocked. The [daycare|camp] is on the other side. They say wait it out"] = "La 31W sigue bloqueada. [La guardería|El campamento] está del otro lado. Dicen que esperemos",
    ["Camp isn't answering. The bus didn't come back. [Somebody went to check|I'm driving out there]"] = "El campamento no contesta. El autobús no volvió. [Alguien fue a ver|Voy para allá en el auto]",
    ["Saw [them|those people] by the swing set. I pushed the dresser in front of the door. Kids are upstairs with me"] = "Vi a [esos|esa gente] junto a los columpios. Empujé la cómoda contra la puerta. Los niños están arriba conmigo",
    ["Two cans of formula left. Church truck [Tuesday|maybe]. I'm stretching it with water"] = "Quedan dos latas de fórmula. El camión de la iglesia [el martes|tal vez]. La estoy rindiendo con agua",
    ["We're closed. Your last check is [$312|$287]. It's [under the mat|in the drop box]. I'm sorry"] = "Cerramos. Tu último cheque es de [$312|$287]. Está [bajo el tapete|en el buzón]. Lo siento",
    ["Store's locked for good. Final check is in the office drop box. [Bring ID|Take care of yourself]"] = "La tienda cerró para siempre. El último cheque está en el buzón de la oficina. [Trae identificación|Cuídate]",
    ["Gates locked this morning. Payroll is in the trailer [Friday|Monday]. Sign the book"] = "Cerraron las rejas esta mañana. La nómina está en el tráiler el [viernes|lunes]. Firma el libro",
    ["Skeleton crew only. Don't come in. Checks are held at the courthouse until the roads open"] = "Solo personal mínimo. No vengas. Los cheques se quedan en el juzgado hasta que abran las carreteras",
    ["The truck got turned back at the fence. Shelves are empty. There's no work. Go home to your people"] = "Regresaron al camión en la cerca. Los estantes están vacíos. No hay trabajo. Vete a casa con los tuyos",
    ["upstairs for signal. one bar if i hold it by the window. [u there|answer me]"] = "arriba por señal. una rayita si lo pego a la ventana. [estás ahí|contéstame]",
    ["Gus says the horses screamed all night down by the river. He's never heard that"] = "Gus dice que los caballos relincharon toda la noche allá por el río. Nunca había oído eso",
    ["bobby went looking for travis last night. no word. his phones off"] = "bobby fue a buscar a travis anoche. nada. tiene el teléfono apagado",
    ["mom cant stop crying. dads at the plant. its just me and her here"] = "mamá no para de llorar. papá está en la planta. aquí solo estamos ella y yo",
    ["the wedding place called. cancelled. deposit's gone. [who cares now|doesnt matter]"] = "llamaron del salón de la boda. cancelado. el depósito se perdió. [a quién le importa ya|no importa]",
    ["found dads CB in the garage. voices on channel 9 but i cant make them out. [still listening|its so far away]"] = "encontré el CB de papá en el garaje. voces en el canal 9 pero no les entiendo. [sigo escuchando|se oye tan lejos]",
    ["both bridges blocked. concrete barriers and soldiers. [nobody crossing|they turned a guy around at gunpoint]"] = "los dos puentes bloqueados. barreras de concreto y soldados. [nadie cruza|regresaron a un tipo apuntándole]",
    ["kayla tried the interstate north. soldiers at every ramp. shes [walking back|staying with a friend]"] = "kayla intentó por la interestatal al norte. soldados en cada rampa. [se está regresando a pie|se queda con una amiga]",
    ["Water's almost gone on our street. I filled the tub. Boil anything you drink"] = "Ya casi no hay agua en nuestra calle. Llené la tina. Hierve todo lo que tomes",
    ["Tony's last text was 3 hours ago. At the hospital. Don't wait for me he said"] = "El último mensaje de Tony fue hace 3 horas. En el hospital. No me esperen, dijo",
    ["Curfew at 9. Heard boots on the porch last night. Don't answer the door for anybody"] = "Toque de queda a las 9. Anoche se oyeron botas en el porche. No le abras la puerta a nadie",
    ["Grandma's neighbor across the hall isn't answering. [Her door's open|I'm going over]"] = "La vecina de enfrente de la abuela no contesta. [Su puerta está abierta|Voy a ir]",
    ["The ferry's chained shut. We're stuck on this side. [Stay put|Come to the lake]"] = "El ferry tiene cadena. Estamos atorados de este lado. [No te muevas|Vente al lago]",
    ["the old man down the road didnt answer his door. car's there. papers piling up"] = "el viejito de más abajo no abrió la puerta. su auto está ahí. los periódicos se están amontonando",
    ["Grandma's neighbor left in a hurry last night. Door open, dog loose. I'm taking the dog"] = "El vecino de la abuela se fue a toda prisa anoche. La puerta abierta, el perro suelto. Me voy a quedar con el perro",
    ["all the lake houses are empty now. keys under the mats. its so quiet you can hear the water"] = "todas las casas del lago están vacías. las llaves bajo los tapetes. hay tanto silencio q se oye el agua",
    ["Another site just dropped. Ray got turned back at the checkpoint. The Army won't let the truck through"] = "Se acaba de caer otra antena. A Ray lo regresaron en el retén. El Ejército no deja pasar la camioneta",
    ["The new girl didn't come in. Her mother called crying. Somebody at their door. I said I'd pray"] = "La chica nueva no vino. Su mamá llamó llorando. Alguien en su puerta. Le dije que iba a rezar",
    ["Two sites on generator. Maybe three days of diesel. I'm sleeping in the break room. Don't worry about me, hon"] = "Dos antenas con generador. Quizá tres días de diésel. Estoy durmiendo en la sala de descanso. No te preocupes por mí, cariño",
    ["If you're reading this, the network's still up. Call your people while you can. Dot"] = "Si estás leyendo esto, la red sigue funcionando. Llama a los tuyos mientras puedas. Dot",
    ["the janitors still in the school. lights on at night. [i see him at the window|hes all alone in there]"] = "el conserje sigue en la escuela. luces prendidas de noche. [lo veo en la ventana|está solito ahí adentro]",
    ["mr peterson's car hasnt moved from the school lot in [two|three] days. his window's down"] = "el auto del sr peterson no se ha movido del estacionamiento de la escuela en [dos|tres] días. tiene la ventana abajo",
    ["The school freezers are thawing. You can smell it from the street. Nobody will open the kitchen"] = "Los congeladores de la escuela se están descongelando. Se huele desde la calle. Nadie quiere abrir la cocina",
    ["The principal's wife came by. He never came home. I gave her the spare key"] = "Vino la esposa del director. Él nunca volvió a casa. Le di la llave de repuesto",
    ["Don't come in this week. The boss said lock it and walk away. Tips are in the safe. Who knows"] = "No vengas esta semana. El jefe dijo que cerremos y nos vayamos. Las propinas están en la caja fuerte. Quién sabe",
    ["Danny's last text was 4 hours ago. Mom I'm cold. The number just rings now"] = "El último mensaje de Danny fue hace 4 horas. Mamá tengo frío. Ahora el número solo suena",
    ["Saw a Humvee on 31W at the checkpoint. Door open. His cover on the seat. It might not be his"] = "Vi un Humvee en el retén de la 31W. La puerta abierta. Su gorra en el asiento. Puede que no sea la suya",
    ["the base PA has been playing taps on a loop since midnight. you can hear it in west point"] = "los altavoces de la base tocan el toque de silencio una y otra vez desde medianoche. se oye en west point",
    ["Two soldiers went to the Coyles' door. Mrs. Coyle didn't scream. She just nodded"] = "Dos soldados fueron a la puerta de los Coyle. La Sra. Coyle no gritó. Solo asintió",
    ["Marcus texted: if you read this, go to the cabin. Don't wait for me"] = "Marcus escribió: si lees esto, vete a la cabaña. No me esperes",
    ["The dog growled at the bedroom door all night. I'm sleeping on the couch"] = "El perro le gruñó a la puerta del cuarto toda la noche. Estoy durmiendo en el sillón",
    ["left the back door open for the cat. two days. food bowl still full"] = "dejé la puerta de atrás abierta para el gato. dos días. el plato de comida sigue lleno",
    ["Neighbor's horse is in our yard with the saddle still on. Nobody's come for it"] = "El caballo del vecino está en nuestro patio todavía ensillado. Nadie ha venido por él",
    ["The cat keeps scratching at the attic hatch. All night. I don't want to open it"] = "El gato sigue rascando la trampilla del ático. Toda la noche. No la quiero abrir",
    ["the prayer chain is down to [12|8] names. they stopped reading them out loud"] = "la cadena de oración ya solo tiene [12|8] nombres. dejaron de leerlos en voz alta",
    ["Pastor Glen didn't come to the door this morning. They say he's resting. Let him be"] = "El pastor Glen no salió a la puerta esta mañana. Dicen que está descansando. Déjenlo",
    ["the funeral is [tuesday|wednesday]. no pastor. graveside only. family only"] = "el funeral es el [martes|miércoles]. sin pastor. solo en el panteón. solo la familia",
    ["The deacon went home to the Lord last night. No service. We buried him ourselves"] = "El diácono se fue con el Señor anoche. Sin servicio. Lo enterramos nosotros",
    ["The kitchen still smells like Wednesday supper. Cornbread in the fridge. I ate alone"] = "La cocina todavía huele a la cena del miércoles. Pan de maíz en el refri. Comí sin compañía",
    ["some preacher on channel 19 shouting about judgment at 3am. somebody keyed over him with Psalm 23. then nothing"] = "un predicador en el canal 19 gritando del juicio a las 3am. alguien le habló encima con el Salmo 23. luego nada",
    ["The ring's still in the drawer. I never gave it to you. The roads are gone now"] = "El anillo sigue en el cajón. Nunca te lo di. Ya no hay caminos",
    ["Your father took the truck to look for {partner}. He hasn't called"] = "Tu papá se llevó la camioneta a buscar a {partner}. No ha llamado",
    ["The dress is in the closet. Tags still on. [Tell your mom|I'll tell her]"] = "El vestido está en el clóset. Todavía con etiquetas. [Dile a tu mamá|Yo le digo]",
    ["Can't reach [Grandma|your aunt] on the house phone. Can you [drive by|check on her] if the roads are open"] = "No logro comunicarme con [la abuela|tu tía] al teléfono de la casa. ¿Puedes [pasar por ahí|ir a verla] si están abiertos los caminos?",
    ["went to the kroger. [doors chained|lot full of cops]. [a deputy|some cop] said curfew at 8"] = "fui al kroger. [puertas con cadena|el estacionamiento lleno de policías]. [un alguacil|un policía] dijo toque de queda a las 8",
    ["gun store in irvington [sold out|closed up]. guy said [people at the door all day|dont come back]"] = "la armería de irvington [se quedó sin nada|cerró]. el tipo dijo [q hubo gente en la puerta todo el día|q no vuelvan]",
    ["motel's full. [nobody's checking out|people sleeping in their cars] [in the lot|out back]"] = "el motel está lleno. [nadie se va|gente durmiendo en sus autos] [en el estacionamiento|atrás]",
}
